using Microsoft.ML.Data;

namespace ChurnPredictor.Models;

public class CustomerData
{
    [LoadColumn(0)]
    public float Age { get; set; }

    [LoadColumn(1)]
    public float Income { get; set; }

    [LoadColumn(2)]
    public string Region { get; set; } = string.Empty;

    [LoadColumn(3)]
    public float PurchaseHistory { get; set; }

    [LoadColumn(4)]
    public string Churned { get; set; } = string.Empty;
}

public class ChurnPrediction
{
    [ColumnName("PredictedLabel")]
    public bool PredictedLabel { get; set; }

    public float Probability { get; set; }

    public float Score { get; set; }
}

using Microsoft.ML;
using ChurnPredictor.Models;

namespace ChurnPredictor.Services;

public class ChurnModelService
{
    private readonly ILogger<ChurnModelService> _logger;
    private readonly MLContext _mlContext;
    private readonly string _dataPath = Path.Combine("Data", "customers.csv");
    private readonly string _modelPath = Path.Combine("Data", "ChurnModel.zip");
    private ITransformer? _model;

    public ChurnModelService(ILogger<ChurnModelService> logger)
    {
        _logger = logger;
        _mlContext = new MLContext(seed: 42);
    }

    public void TrainAndEvaluate()
    {
        var data = _mlContext.Data.LoadFromTextFile<CustomerData>(
            _dataPath, hasHeader: true, separatorChar: ',');

        var split = _mlContext.Data.TrainTestSplit(data, testFraction: 0.2);

        var pipeline = _mlContext.Transforms.Conversion
                .MapValueToKey("Label", "Churned")
            .Append(_mlContext.Transforms.Categorical
                .OneHotEncoding("RegionEncoded", "Region"))
            .Append(_mlContext.Transforms.Concatenate("Features",
                "Age", "Income", "RegionEncoded", "PurchaseHistory"))
            .Append(_mlContext.BinaryClassification.Trainers
                .SdcaLogisticRegression(labelColumnName: "Label", featureColumnName: "Features"))
            .Append(_mlContext.Transforms.Conversion
                .MapKeyToValue("PredictedLabel"));

        _model = pipeline.Fit(split.TrainSet);

        var predictions = _model.Transform(split.TestSet);
        var metrics = _mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");

        _logger.LogInformation("Model trained — AUC: {AUC:F4}, F1: {F1:F4}",
            metrics.AreaUnderRocCurve, metrics.F1Score);

        _mlContext.Model.Save(_model, split.TrainSet.Schema, _modelPath);
        _logger.LogInformation("Model saved to {Path}", _modelPath);
    }

    public ITransformer LoadModel()
    {
        _model = _mlContext.Model.Load(_modelPath, out _);
        return _model;
    }
}

using Microsoft.Extensions.ML;
using ChurnPredictor.Models;

namespace ChurnPredictor.Services;

public class ChurnPredictionService
{
    private readonly PredictionEnginePool<CustomerData, ChurnPrediction> _pool;

    public ChurnPredictionService(PredictionEnginePool<CustomerData, ChurnPrediction> pool)
    {
        _pool = pool;
    }

    public ChurnPrediction Predict(CustomerData input)
    {
        return _pool.Predict(input);
    }
}

