using Microsoft.Extensions.ML;
using ChurnPredictor.Models;
using ChurnPredictor.Services;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddSingleton<ChurnModelService>();
builder.Services.AddPredictionEnginePool<CustomerData, ChurnPrediction>()
    .FromFile(Path.Combine("Data", "ChurnModel.zip"));
builder.Services.AddScoped<ChurnPredictionService>();

var app = builder.Build();

// Train model on startup
var modelService = app.Services.GetRequiredService<ChurnModelService>();
modelService.TrainAndEvaluate();

app.MapGet("/", () => "Churn Predictor API is running");

app.MapPost("/predict", (PredictRequest request, ChurnPredictionService predictionService) =>
{
    var input = new CustomerData
    {
        Age = request.Age,
        Income = request.Income,
        Region = request.Region ?? string.Empty,
        PurchaseHistory = request.PurchaseHistory
    };

    var result = predictionService.Predict(input);

    return Results.Ok(new { willChurn = result.PredictedLabel, probability = result.Probability });
});

app.Run();

record PredictRequest(float Age, float Income, string? Region, float PurchaseHistory);

